-- ============ SKILL BENCHMARKS UPDATE ============
-- Aggregate from answer_events

UPDATE skill_benchmarks sb SET
    total_attempts = sub.total,
    total_correct = sub.correct,
    success_rate_grade_5 = ROUND(sub.correct::numeric / GREATEST(sub.total, 1) * 100, 2),
    last_calculated_at = NOW()
FROM (
    SELECT skill_id, COUNT(*) as total, SUM(CASE WHEN is_correct THEN 1 ELSE 0 END) as correct
    FROM answer_events
    WHERE client_version = 'synthetic-1.0'
    GROUP BY skill_id
) sub
WHERE sb.skill_id = sub.skill_id;


COMMIT;

-- Total: 994 tasks, 133 templates, 800 events